      >
        <ComboboxInput id="warehouse-city" placeholder="输入城市名" />
        <ComboboxPopup>
          <ComboboxEmpty>没有匹配的城市</ComboboxEmpty>
          <ComboboxList>
            {(city: string) => (
              <ComboboxItem key={city} value={city}>
                {city}
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxPopup>
      </Combobox>
    </div>
  );
}

