      <OTPField
        length={6}
        value={value}
        onValueChange={(next) => {
          setValue(next);
          setStatus("idle");
        }}
        onValueComplete={verify}
        disabled={status === "checking" || status === "ok"}
        aria-label="邮箱验证码"
        aria-describedby={status === "error" ? statusId : undefined}
      >
        {Array.from({ length: 6 }, (_, index) => (
          <OTPFieldInput key={index} aria-invalid={status === "error" || undefined} />
