const groups = [
  {
    label: "通用型",
    items: [
      { label: "g7.large · 2 核 8 GB", value: "g7.large" },
      { label: "g7.xlarge · 4 核 16 GB", value: "g7.xlarge" },
      { label: "g7.2xlarge · 8 核 32 GB", value: "g7.2xlarge", disabled: true },
