          全部收起
        </Button>
      </div>
      <Tree
        expanded={expanded}
        label="门店"
        nodes={nodes}
        onExpandedChange={setExpanded}
        onValueChange={(id, node) => {
          setValue(id);
          setName(node.label);
        }}
        value={value}
      />
      <p className="text-muted-foreground text-sm">
        当前选中：<span className="font-medium text-foreground">{name}</span>
      </p>
    </div>
  );
}

